(window.__AC=window.__AC||{});__AC["assets_vo"]=(__AC["assets_vo"]||'')+"// Озвучка всех реплик (Silero v4, явные ударения)\nwindow.ASSETS_LINES=window.ASSETS_LINES||{};window.ASSETS_AUDIO=window.ASSETS_AUDIO||{};\nObject.assign(window.ASSETS_LINES,{\"i1\": {\"s\": \"narr\", \"t\": \"Хальда всегда смотрит на своё солнце одной стороной. Там, где вечный полдень, плавится камень. Там, где вечная ночь, замерзает сам воздух.\"}, \"i2\": {\"s\": \"narr\", \"t\": \"Девятьсот лет назад сюда упал корабль. Колонисты выжили. Но со временем забыли, откуда пришли.\"}, \"i3\": {\"s\": \"narr\", \"t\": \"Жить можно только в сумерках, на узкой Линии Зари. Но она ползёт. Поэтому мы построили города на колёсах. И никогда не останавливаемся.\"}, \"i4\": {\"s\": \"irma\", \"t\": \"Отстал на день — замёрз. Обогнал на день — сгорел. Мы живём ровно посередине. И это называется дом.\"}, \"i5\": {\"s\": \"narr\", \"t\": \"Три дня назад солнечная вспышка разорвала путь впереди города Орсо. Город встал. И его хвост начал плавиться.\"}, \"i6\": {\"s\": \"irma\", \"t\": \"Меня зовут Ирма Кесс. Я путевая обходчица. Моя работа — чтобы у города была дорога. Даже когда её нет.\"}, \"r_start\": {\"s\": \"avram\", \"t\": \"Ирма, приём! Хвост горит. Совет решил ползти к разрыву — стоять больше нельзя. Пробирайся к голове состава и почини путь, пока мы не дошли до края.\"}, \"r_start2\": {\"s\": \"irma\", \"t\": \"Поняла, дед Аврам. Иду.\"}, \"r_heat\": {\"s\": \"avram\", \"t\": \"Осторожно со светом. Солнце в щелях жжёт насквозь. Держись тени и следи за костюмом.\"}, \"r_vent\": {\"s\": \"irma\", \"t\": \"Клапаны травят пар. Надо ловить момент.\"}, \"r_grapple\": {\"s\": \"irma\", \"t\": \"Сцепку оборвало. Ну, Клюв, не подведи.\"}, \"r_pechka\": {\"s\": \"avram\", \"t\": \"Твоя Печка копит жар на свету. Им можно сделать рывок. А впереди он ещё и согреет.\"}, \"r_chase\": {\"s\": \"avram\", \"t\": \"Ирма! Перегрев идёт волной, вагоны рушатся прямо за тобой! Беги! Не оглядывайся!\"}, \"r_chase_end\": {\"s\": \"irma\", \"t\": \"Проскочила. Дед, я на крышах головных вагонов.\"}, \"r_cold\": {\"s\": \"avram\", \"t\": \"Впереди тень. Холод там злой. Грейся от Печки и от жаровен. И не стой на месте.\"}, \"r_sentinel\": {\"s\": \"avram\", \"t\": \"Вижу фонарщиков Гильдии. Странно. Что им делать у нашего города? Не попадайся в их луч — он жжёт не хуже солнца.\"}, \"r_end\": {\"s\": \"irma\", \"t\": \"Вот он, разрыв. Сейчас. Сейчас поставлю.\"}, \"e1\": {\"s\": \"avram\", \"t\": \"Ирма... Я перехватил приказ Гильдии. Орсо исключён из Кольцевого пути. Ремонт не планируется. Нас решили бросить.\"}, \"e2\": {\"s\": \"irma\", \"t\": \"Значит, дорогу мы проложим сами. Через полдень. Через ночь. Куда угодно.\"}, \"e3\": {\"s\": \"narr\", \"t\": \"Так начинается путь Ирмы Кесс. Продолжение следует.\"}, \"d1\": {\"s\": \"irma\", \"t\": \"Ещё раз.\"}, \"d2\": {\"s\": \"irma\", \"t\": \"Не сейчас. Не так.\"}, \"l2_a\": {\"s\": \"avram\", \"t\": \"Ирма, город встал перед Старым мостом. Пролёты обрушены. Пройди по фермам и открой путевой затвор на той стороне.\"}, \"l2_b\": {\"s\": \"irma\", \"t\": \"Ветер с ночной стороны. Держусь крепче.\"}, \"l2_wind\": {\"s\": \"avram\", \"t\": \"Порывы идут волнами. Когда загудят тросы — прячься за опору и пережди.\"}, \"l2_zip\": {\"s\": \"irma\", \"t\": \"Старые тросы канатки. Зацеплюсь Клювом — и с ветерком.\"}, \"l2_drone\": {\"s\": \"avram\", \"t\": \"Над мостом кружит фонарщик Гильдии. Что они здесь ищут? Не попадайся в луч.\"}, \"l2_end\": {\"s\": \"irma\", \"t\": \"Затвор открыт! Дед, веди Орсо на мост. А я — дальше, в тень.\"}, \"l3_a\": {\"s\": \"avram\", \"t\": \"Дальше только ночь. Стрелка обходного пути вмёрзла в лёд. Без неё нам не пройти.\"}, \"l3_ice\": {\"s\": \"irma\", \"t\": \"Лёд как стекло. Тормозить заранее.\"}, \"l3_icicle\": {\"s\": \"avram\", \"t\": \"Сосульки над путями тяжёлые, как рельсы. Услышишь треск — уходи.\"}, \"s1\": {\"s\": \"narr\", \"t\": \"Бортовой журнал «Зари», первый день после посадки. Корабль больше не взлетит. Мы остаёмся. Пусть дети запомнят: мы пришли со звёзд.\"}, \"s2\": {\"s\": \"narr\", \"t\": \"Записка путейца: рельсы кладут на ходу. Отстанешь от укладчиков на час — и твоя смена станет последней.\"}, \"s3\": {\"s\": \"narr\", \"t\": \"Устав Гильдии Фонарщиков, статья первая: свет принадлежит тем, кто его хранит.\"}, \"s4\": {\"s\": \"narr\", \"t\": \"Детская считалка Орсо: солнце жжёт, а ночь не ждёт. Кто устал — тот не дойдёт.\"}, \"s5\": {\"s\": \"narr\", \"t\": \"Журнал «Зари», последняя запись. Мы замкнули путь в кольцо. Кто держит кольцо — держит всех. Не отдавайте его одному.\"}, \"s6\": {\"s\": \"narr\", \"t\": \"Пометка на полях, свежими чернилами: «Орсо — лишний. Снять с кольца». Подпись: Гильдия.\"}, \"c1\": {\"s\": \"irma\", \"t\": \"Хвост горит. Значит, вперёд.\"}, \"l4_a\": {\"s\": \"avram\", \"t\": \"Ирма, приём… Связь тает. Ты на прямом пути колонистов. Дальше только Пекло. Иди от тени к тени.\"}, \"l4_b\": {\"s\": \"irma\", \"t\": \"Здесь солнце не садится. Значит, и я не сяду.\"}, \"l4_cloak\": {\"s\": \"irma\", \"t\": \"Затвор на солнечном приёмнике. Светлая сторона плаща отразит луч. Только бы не свариться.\"}, \"l4_crate\": {\"s\": \"irma\", \"t\": \"Ящик на уступе. Клюв дотянется. Стащу — и будет ступенька. А заодно и тень.\"}, \"l4_shade\": {\"s\": \"irma\", \"t\": \"Тени башен ползут. Иду вместе с ними.\"}, \"l4_sola1\": {\"s\": \"sola\", \"t\": \"Стой! Не беги по песку — черви слышат шаги и чуют жар. Ты из сумеречных? У тебя есть тень… Как красиво.\"}, \"l4_sola2\": {\"s\": \"irma\", \"t\": \"Я Ирма, обходчица из Орсо. Мне нужно пройти Пекло насквозь.\"}, \"l4_sola3\": {\"s\": \"sola\", \"t\": \"Дед говорил: раньше солнце стояло ниже. Оно ползёт быстрее, чем считают Навигаторы. Зеркала это помнят.\"}, \"l4_take_i\": {\"s\": \"irma\", \"t\": \"Пойдёшь со мной? Только держись в моей тени.\"}, \"l4_take\": {\"s\": \"sola\", \"t\": \"Пойду! Я знаю, где спят черви. Пойду низом — встретимся у зеркал.\"}, \"l4_stay_i\": {\"s\": \"irma\", \"t\": \"Оставайся в лагере. Там, куда я иду, хуже, чем здесь.\"}, \"l4_stay\": {\"s\": \"sola\", \"t\": \"Тогда возьми жар из нашего горна. Твоя Печка полна. И возвращайся.\"}, \"l4_worm_s\": {\"s\": \"sola\", \"t\": \"Ирма, под песком червь! Не беги. Иди тихо, пригнувшись, и остывай на камнях.\"}, \"l4_worm_i\": {\"s\": \"irma\", \"t\": \"Песок дрожит. Что-то идёт на тепло. Тише, Ирма. Тише.\"}, \"l4_mirror_s\": {\"s\": \"sola\", \"t\": \"Я здесь! Зеркала передают свет друг другу. Но нижнее повёрнуто не туда — дёрни рычаг наверху.\"}, \"l4_mirror_i\": {\"s\": \"irma\", \"t\": \"Зеркала колонистов. Нижнее смотрит не туда. Рычаг высоко — Клюв достанет.\"}, \"l4_plate\": {\"s\": \"irma\", \"t\": \"Створку держит плита. Моего веса мало — нужен груз.\"}, \"l4_tide\": {\"s\": \"irma\", \"t\": \"Тень уходит! Солнечный прилив! Бегом к семафору!\"}, \"l4_teo\": {\"s\": \"irma\", \"t\": \"Эта метка… Так метил рельсы только Тео. И краска свежая. Тео… ты жив?\"}, \"l4_sola_end\": {\"s\": \"sola\", \"t\": \"Это знак сумеречного. Он прошёл здесь прошлым летом, к Сангре. Я помню его тень.\"}, \"s7\": {\"s\": \"narr\", \"t\": \"Журнал зеркальщиков: тень у Третьей башни стала короче на ладонь. Навигаторам писали трижды. Ответа не было.\"}, \"s8\": {\"s\": \"narr\", \"t\": \"Расписка Гильдии: зеркальные башни отключить. Свет — только для головных городов. Подпись стёрта солью.\"}, \"e4\": {\"s\": \"irma\", \"t\": \"Тео жив. Орсо ждёт. Впереди Сангра и Звёздный Зал. Значит, туда я и иду.\"}, \"l5_a\": {\"s\": \"avram\", \"t\": \"Ирма… слышишь? Сангра глушит связь… Будь осторожна. Гильдия не любит гостей.\"}, \"l5_b\": {\"s\": \"irma\", \"t\": \"Аврам? Аврам! …Пропал. Ладно. Дальше сама.\"}, \"l5_gate\": {\"s\": \"irma\", \"t\": \"Шлюз заперт. Кольцо-рычаг над воротами — дёрну Клювом.\"}, \"l5_lift\": {\"s\": \"irma\", \"t\": \"Грузовой лифт. Закачу на него ящик — и поеду вместе с ним.\"}, \"l5_steam\": {\"s\": \"irma\", \"t\": \"Паровые кварталы. Трубы ещё дышат. Иду в паузах между выбросами.\"}, \"l5_lamp\": {\"s\": \"veil\", \"t\": \"Внимание. В секторе посторонний. Фонари, зачистить квартал.\"}, \"l5_hide\": {\"s\": \"irma\", \"t\": \"Фонари Гильдии. Свет не проходит сквозь железо. Держусь за укрытиями.\"}, \"l5_mara1\": {\"s\": \"mara\", \"t\": \"Стой! Ещё шаг — и тебя подпалит заслонка. Ты кто такая?\"}, \"l5_mara2\": {\"s\": \"irma\", \"t\": \"Ирма. С «Зари». Ищу человека. Его зовут Тео.\"}, \"l5_mara3\": {\"s\": \"mara\", \"t\": \"Тео? Он чинил с нами сердце Хребта. А потом ушёл — и сказал, что ты придёшь. Я Мара. Последний механик Сангры.\"}, \"l5_mara4\": {\"s\": \"mara\", \"t\": \"Город не умер. Его усыпили. Вейл снял три предохранителя — и Хребет встал.\"}, \"l5_mara5\": {\"s\": \"mara\", \"t\": \"Запустим Хребет — и Сангра поедет снова. Помоги мне, и я отдам тебе то, что оставил Тео.\"}, \"l5_sola_m\": {\"s\": \"sola\", \"t\": \"Механик? Здесь? Значит, город ещё живой.\"}, \"l5_light\": {\"s\": \"irma\", \"t\": \"Световой колодец. Встану в столб света — плащ поймает луч.\"}, \"l5_wheel\": {\"s\": \"mara\", \"t\": \"Колесо Хребта! Прыгай на лопасти, пока оно крутится!\"}, \"l5_depot\": {\"s\": \"mara\", \"t\": \"Депо затопило, когда встали насосы. Понтоны тонут под весом — не стой на них долго!\"}, \"l5_fuse\": {\"s\": \"mara\", \"t\": \"Вот они — три предохранителя. Две плиты под грузом и один приёмник света. Зажги все три лампы — и ворота откроются.\"}, \"l5_sola_s\": {\"s\": \"sola\", \"t\": \"Я помню зеркала, Ирма. Свет найдёт дорогу.\"}, \"l5_sola_i\": {\"s\": \"irma\", \"t\": \"Сола бы сейчас пригодилась… Справлюсь сама.\"}, \"l5_purge\": {\"s\": \"veil\", \"t\": \"Несанкционированный запуск. Начинаю продувку сектора. Грузу — сохранять спокойствие.\"}, \"l5_run\": {\"s\": \"mara\", \"t\": \"Он пускает пар по всей линии! Бегом к сердцу, Ирма! Не оглядывайся!\"}, \"l5_end\": {\"s\": \"irma\", \"t\": \"Сердце Хребта. Держись, старик… Сейчас.\"}, \"l5_end2\": {\"s\": \"mara\", \"t\": \"Слышишь? Он дышит! Сангра дышит!\"}, \"l5_teo\": {\"s\": \"mara\", \"t\": \"Это оставил Тео. Карта к Звёздному Залу. Он сказал: «Кольцо — это не путь. Кольцо — это цепь».\"}, \"e5\": {\"s\": \"irma\", \"t\": \"Звёздный Зал. Там всё началось. Там я и закончу.\"}, \"s9\": {\"s\": \"narr\", \"t\": \"Приказ номер сорок. Сангру снять с Кольца. Жителей считать грузом. Подпись — Смотритель Вейл.\"}, \"s10\": {\"s\": \"irma\", \"t\": \"Записка Тео: «Не верь фонарям. Они светят не для нас».\"}, \"l6_a\": {\"s\": \"irma\", \"t\": \"Ну здравствуй, «Заря». Метка Тео — у шлюза. Он прошёл здесь.\"}, \"l6_b\": {\"s\": \"marar\", \"t\": \"Ирма, слышишь? Это Мара. Рация Тео берёт до самого Зала. Я с тобой.\"}, \"l6_cache\": {\"s\": \"irma\", \"t\": \"Тайник Тео. А внутри… часы?\"}, \"l6_chrono\": {\"s\": \"teor\", \"t\": \"Если ты это нашла, малая, — бери Хронометр Навигаторов. Нажми — и механизмы Зала замрут на три вдоха. Не больше.\"}, \"l6_try\": {\"s\": \"irma\", \"t\": \"Мост носится как бешеный. Ну что ж — остановим время.\"}, \"l6_gear\": {\"s\": \"irma\", \"t\": \"Шестерня крутится слишком быстро. Поймаю ступень — и замру.\"}, \"l6_timer\": {\"s\": \"marar\", \"t\": \"Эти ворота закрываются сами. Дёрнешь кольцо — успей, пока горят лампы.\"}, \"l6_steam\": {\"s\": \"irma\", \"t\": \"Пар бьёт почти без паузы. Значит, паузу сделаю я.\"}, \"l6_press\": {\"s\": \"marar\", \"t\": \"Паровые прессы! Они плющат рельсы в лист. Не стой под ними, Ирма!\"}, \"l6_lamp\": {\"s\": \"veil\", \"t\": \"Говорит Смотритель Вейл. Зал закрыт. Фонари видят всё.\"}, \"l6_lamp2\": {\"s\": \"irma\", \"t\": \"Фонари видят. Но фонари — тоже механизм.\"}, \"l6_pend\": {\"s\": \"irma\", \"t\": \"Кольца на цепях качаются. Замру в нужный миг — и перелечу.\"}, \"l6_mirror\": {\"s\": \"marar\", \"t\": \"Зеркала там вращаются по часам Навигаторов. Лови миг, когда оба смотрят куда надо.\"}, \"l6_sola_s\": {\"s\": \"sola\", \"t\": \"Два зеркала, Ирма. Как два вдоха. Жди, пока они совпадут.\"}, \"l6_sola_i\": {\"s\": \"irma\", \"t\": \"Сола бы сказала: свет терпелив. Подожду.\"}, \"l6_archive\": {\"s\": \"irma\", \"t\": \"Архив курсов. Тео что-то здесь оставил.\"}, \"l6_teo1\": {\"s\": \"teor\", \"t\": \"Запись Тео. Я сравнил таблицы Навигаторов с журналом «Зари». Солнце ускоряется. Каждый год — на ладонь.\"}, \"l6_teo2\": {\"s\": \"teor\", \"t\": \"Навигаторы знают уже сорок лет. Они не спасают Кольцо. Они решают, кого с него снять.\"}, \"l6_teo3\": {\"s\": \"irma\", \"t\": \"Орсо… Сангра… Они не отстали. Их скинули, чтобы голова успевала.\"}, \"l6_keys\": {\"s\": \"marar\", \"t\": \"Подъём в Зал заперт на три ключа. Как у нас в Сангре. Зажги все три лампы.\"}, \"l6_lift\": {\"s\": \"marar\", \"t\": \"Лифт идёт до самого верха. Останови его на полпути — там уступ.\"}, \"l6_shaft\": {\"s\": \"irma\", \"t\": \"Часовая шахта. Ничего, «Заря». Я умею лазить по твоим часам.\"}, \"l6_veil2\": {\"s\": \"veil\", \"t\": \"Ирма из Орсо. Я знаю, кто ты. Вернись — и твой город поедет дальше. Это честная сделка.\"}, \"l6_veil3\": {\"s\": \"irma\", \"t\": \"Сделки с фонарями я уже видела. Нет.\"}, \"l6_dome\": {\"s\": \"marar\", \"t\": \"Ты почти под куполом! Тео где-то там — я слышу его на частоте!\"}, \"l6_mirrorbig\": {\"s\": \"veil\", \"t\": \"Развернуть Большое Зеркало. Выжечь галерею.\"}, \"l6_run\": {\"s\": \"irma\", \"t\": \"Он жжёт галерею! Бегом!\"}, \"l6_end\": {\"s\": \"irma\", \"t\": \"Тео!\"}, \"l6_teo_a\": {\"s\": \"teo\", \"t\": \"Малая… Всё-таки дошла. Я знал.\"}, \"l6_teo_b\": {\"s\": \"teo\", \"t\": \"Это Голос «Зари» — передатчик корабля. Его слышат все города Кольца. Запусти его — и правду услышат все.\"}, \"l6_fin1\": {\"s\": \"teo\", \"t\": \"Говорит «Заря». Всем городам Кольца. Солнце ускоряется — и Навигаторы это скрывают.\"}, \"l6_fin2\": {\"s\": \"veil\", \"t\": \"Ты не понимаешь, что сделала. Теперь побегут все.\"}, \"l6_fin3\": {\"s\": \"irma\", \"t\": \"Пусть бегут. Вместе. Никого больше не снимут с Кольца.\"}, \"e6\": {\"s\": \"narr\", \"t\": \"В ту ночь все города Кольца услышали голос со звёзд. Продолжение следует.\"}, \"s11\": {\"s\": \"narr\", \"t\": \"Таблицы Навигаторов: поправка на дрейф солнца. Править ежегодно. Никому не сообщать.\"}, \"s12\": {\"s\": \"narr\", \"t\": \"Письмо Вейла, неотправленное: «Я тоже из хвоста. Меня сняли первым».\"}, \"st5_1\": {\"s\": \"narr\", \"t\": \"Метка Тео вела на север — туда, где кончаются карты Гильдии.\"}, \"st5_2\": {\"s\": \"narr\", \"t\": \"В Пекле Ирма узнала правду: солнце ползёт быстрее, чем считают Навигаторы. А Гильдия гасит зеркала и снимает с Кольца целые города.\"}, \"st5_3\": {\"s\": \"narr\", \"t\": \"На краю соляной равнины стоит Сангра — город-ковчег в тысячу вагонов. Он не отстал от Кольца. Его остановили.\"}, \"st5_4\": {\"s\": \"irma\", \"t\": \"Если Тео жив — он там. И если Гильдия что-то прячет — тоже там.\"}, \"st5_5\": {\"s\": \"veil\", \"t\": \"Говорит Смотритель Вейл. Сангра закрыта по решению Кольца. Покиньте зону. Фонари не ошибаются.\"}, \"st5_6\": {\"s\": \"narr\", \"t\": \"Но внутри мёртвого города кто-то всё ещё зажигает огонь.\"}, \"st6_1\": {\"s\": \"narr\", \"t\": \"Сердце Хребта забилось, и Сангра снова поехала. А Мара отдала Ирме то, что оставил Тео: карту к Звёздному Залу.\"}, \"st6_2\": {\"s\": \"narr\", \"t\": \"Звёздный Зал — мостик старой «Зари», корабля, на котором предки пришли со звёзд. Теперь там сидят Навигаторы Гильдии.\"}, \"st6_3\": {\"s\": \"narr\", \"t\": \"Девятьсот лет они считают бег солнца и решают, куда ехать Кольцу. И кого с него снять.\"}, \"st6_4\": {\"s\": \"irma\", \"t\": \"Тео писал: «Кольцо — это не путь. Кольцо — это цепь». Я должна узнать почему.\"}, \"st6_5\": {\"s\": \"veil\", \"t\": \"Всем постам. Посторонняя на нижних ярусах. Из Зала не выпускать.\"}});\nObject.assign(window.ASSETS_AUDIO,{\"v_c1\": \"\", \"v_d1\": \"\", \"v_d2\": \"\", \"v_e1\": \"\", \"v_e2\": \"\", \"v_e3\": \"\", \"v_e4\": \"\", \"v_e5\": \"\", \"v_e6\": \"\", \"v_i1\": \"\", \"v_i2\": \"\", \"v_i3\": \"\", \"v_i4\": \"\", \"v_i5\": \"\", \"v_i6\": \"";